import { useState, useContext, useEffect } from "react";
import { ComplaintContext } from "../context/ComplaintContext";
import { useLocation, useNavigate } from "react-router-dom";
import {
  MapContainer,
  TileLayer,
  Marker,
  useMapEvents
} from "react-leaflet";
import L from "leaflet";
import "../styles/global.css";

/* ⭐ Fix Leaflet marker bug */
delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl:
    "https://unpkg.com/leaflet@1.7.1/dist/images/marker-icon-2x.png",
  iconUrl:
    "https://unpkg.com/leaflet@1.7.1/dist/images/marker-icon.png",
  shadowUrl:
    "https://unpkg.com/leaflet@1.7.1/dist/images/marker-shadow.png"
});

/* ⭐ Map click handler */
function LocationPicker({ setPosition }) {
  useMapEvents({
    click(e) {
      setPosition(e.latlng);
    }
  });
  return null;
}

function AddComplaint() {
  const { addComplaint } = useContext(ComplaintContext);
  const { state } = useLocation();
  const navigate = useNavigate();

  const department = state?.department || "General";
  const categories = [...(state?.categories || []), "Other"];

  const [category,setCategory]=useState("");
  const [custom,setCustom]=useState("");
  const [desc,setDesc]=useState("");

  /* ⭐ location states */
  const [query,setQuery]=useState("");
  const [suggestions,setSuggestions]=useState([]);
  const [position,setPosition]=useState(null);
  const [address,setAddress]=useState("");

  /* ⭐ image states */
  const [img,setImg]=useState(null);
  const [preview,setPreview]=useState(null);

  /* ⭐ GPS auto detect */
  useEffect(()=>{
    navigator.geolocation.getCurrentPosition((pos)=>{
      setPosition({
        lat:pos.coords.latitude,
        lng:pos.coords.longitude
      });
    });
  },[]);

  /* ⭐ reverse geocode */
  useEffect(()=>{
    if(!position) return;

    fetch(
      `https://nominatim.openstreetmap.org/reverse?format=json&lat=${position.lat}&lon=${position.lng}`
    )
      .then(res=>res.json())
      .then(data=>{
        if(data?.display_name){
          setAddress(data.display_name);
          setQuery(data.display_name);
        }
      });
  },[position]);

  /* ⭐ search India only */
  const searchLocation = async(text)=>{
    setQuery(text);

    if(text.length<3) return;

    const res = await fetch(
      `https://nominatim.openstreetmap.org/search?format=json&q=${text}&countrycodes=in&limit=5`
    );
    const data = await res.json();
    setSuggestions(data);
  }

  /* ⭐ image upload */
  const handleImg=(e)=>{
    const file=e.target.files[0];
    setImg(file);
    setPreview(URL.createObjectURL(file));
  }

  const submit=()=>{
    const finalCat = category==="Other" ? custom : category;

    addComplaint({
      department,
      category:finalCat,
      desc,
      location:address,
      coords:position,
      image:preview,
      status:"Pending",
      timeline:["Submitted"]
    });

    navigate("/track");
  }

  return (
    <div className="complaint-page animated-bg">
      <div className="complaint-card">

        <h2>{department}</h2>

        {/* ⭐ CATEGORY */}
        <select value={category} onChange={(e)=>setCategory(e.target.value)}>
          <option>Select category</option>
          {categories.map(c=><option key={c}>{c}</option>)}
        </select>

        {category==="Other" && (
          <input
            placeholder="Enter custom category"
            value={custom}
            onChange={(e)=>setCustom(e.target.value)}
          />
        )}

        {/* ⭐ DESCRIPTION */}
        <textarea
          placeholder="Describe complaint"
          value={desc}
          onChange={(e)=>setDesc(e.target.value)}
        />

        {/* ⭐ LOCATION SEARCH */}
        <input
          placeholder="Search location (India only)"
          value={query}
          onChange={(e)=>searchLocation(e.target.value)}
        />

        {/* ⭐ Suggestions */}
        {suggestions.length>0 && (
          <div className="suggestions">
            {suggestions.map((s,i)=>(
              <div
                key={i}
                className="suggestion"
                onClick={()=>{
                  const lat=parseFloat(s.lat);
                  const lng=parseFloat(s.lon);
                  setPosition({lat,lng});
                  setAddress(s.display_name);
                  setQuery(s.display_name);
                  setSuggestions([]);
                }}
              >
                {s.display_name}
              </div>
            ))}
          </div>
        )}

        {/* ⭐ MAP */}
        <MapContainer
          center={position || [17.385,78.486]}
          zoom={13}
          style={{height:"250px",borderRadius:"12px"}}
        >
          <TileLayer
            attribution="&copy OpenStreetMap"
            url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
          />

          {position && (
            <Marker
              draggable
              position={position}
              eventHandlers={{
                dragend:(e)=>setPosition(e.target.getLatLng())
              }}
            />
          )}

          <LocationPicker setPosition={setPosition}/>
        </MapContainer>

        {/* ⭐ IMAGE UPLOAD */}
        <label className="upload">
          Upload complaint image
          <input type="file" onChange={handleImg} hidden/>
        </label>

        {preview && <img src={preview} className="img-preview" />}

        <button onClick={submit}>Submit Complaint</button>
      </div>
    </div>
  );
}

export default AddComplaint;
